<?php
require_once dirname(__DIR__).'/app/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect(app_path('index.php'));require_login();verify_csrf();$id=(int)($_POST['listing_id']??0);$back=local_return_url((string)($_POST['return_to']??'index.php'));$s=db()->prepare("SELECT id FROM listings WHERE id=:id AND status='published'");$s->execute([':id'=>$id]);if(!$s->fetchColumn()){flash('error','That listing is not available.');redirect($back);}if(is_favorite($id)){db()->prepare('DELETE FROM favorites WHERE user_id=:u AND listing_id=:l')->execute([':u'=>current_user_id(),':l'=>$id]);flash('success','Removed from your favourites.');}else{db()->prepare('INSERT OR IGNORE INTO favorites(user_id,listing_id) VALUES(:u,:l)')->execute([':u'=>current_user_id(),':l'=>$id]);flash('success','Saved to your favourites.');}redirect($back);
